{"path": "scan_lcp.ps1", "content": "$path = "C:\Users\dmql\Documents\low-code-platform"
if (Test-Path $path) {
    Write-Host "=== low-code-platform (dirs) ==="
    Get-ChildItem -Path $path -Directory | Select-Object Name
    Write-Host "=== low-code-platform (files) ==="
    Get-ChildItem -Path $path -File | Select-Object Name
    Get-ChildItem -Path $path -Recurse -Depth 2 -Exclude "node_modules",".git","__pycache__","dist","build" -File | Select-Object @{N="Path";E={$_.FullName.Substring($path.Length+1)}}
} else {
    Write-Host "PATH NOT FOUND: $path"
}
"}

